typedef enum {
  SCENE_WALK_STRAIGHT = 0,
  SCENE_TURNING,
  SCENE_CROSSWALK_WAIT,
  SCENE_STATIONARY,
  SCENE_UNKNOWN
} scene_mode_t;

typedef enum {
  PROFILE_GENERAL = 0,
  PROFILE_HEARING,
  PROFILE_VISION
} a11y_profile_t;

typedef struct {
  float dist_to_crossing_m; /* <0 表示无效 */
  int congested;
  uint32_t last_update_ms;
} nav_bias_t;

typedef struct {
  float range_m;
  float rel_speed_mps;
  float azimuth_deg;
  float snr;
  uint32_t id;
} radar_target_t;

typedef enum {
  ALERT_NONE = 0,
  ALERT_SOFT,
  ALERT_STRONG,
  ALERT_EMERGENCY
} alert_level_t;
```

### 6.3 策略引擎（示意：含导航偏置）

```c
/* policy.c */

alert_level_t policy_evaluate(const radar_target_t *t,
                              scene_mode_t scene,
                              const nav_bias_t *nav,
                              a11y_profile_t profile,
                              uint32_t now_ms)
{
  float speed_thr = 1.5f;
  float ttc_thr = 3.5f;
  float near_ttc = 1.2f;

  /* 导航预告路口或 IMU 路口/转弯 → 降敏 */
  int crossing =
      (scene == SCENE_TURNING || scene == SCENE_CROSSWALK_WAIT) ||
      (nav && nav->dist_to_crossing_m >= 0.f &&
       nav->dist_to_crossing_m < 30.f &&
       (now_ms - nav->last_update_ms) < 3000);

  if (crossing) {
    speed_thr = 2.5f;
    ttc_thr = 2.0f;
    near_ttc = 1.0f;
  }
  if (nav && nav->congested)
    speed_thr += 0.5f;

  if (t->rel_speed_mps < speed_thr)
    return ALERT_NONE;
  if (t->azimuth_deg < -80.f || t->azimuth_deg > 80.f)
    return ALERT_NONE;

  float ttc = t->range_m / t->rel_speed_mps;
  if (ttc > ttc_thr)
    return ALERT_NONE;

  if (crossing && (ttc > near_ttc || t->range_m > 4.0f))
    return ALERT_NONE;

  if (ttc < 1.0f)
    return ALERT_EMERGENCY;
  if (ttc < 2.0f)
    return ALERT_STRONG;
  return ALERT_SOFT;
  /* profile 不改变探测门限，只影响后续 haptic/earcon 通道选择 */
}
```

### 6.4 场景融合与输出通道（示意）

```c
scene_mode_t merge_scene(scene_mode_t imu, const nav_bias_t *nav, uint32_t now_ms)
{
  int nav_crossing = nav && nav->dist_to_crossing_m >= 0.f &&
                     nav->dist_to_crossing_m < 30.f &&
                     (now_ms - nav->last_update_ms) < 3000;
  if (imu == SCENE_TURNING)
    return SCENE_TURNING;          /* 行人未按导航走时信 IMU */
  if (nav_crossing)
    return SCENE_CROSSWALK_WAIT;
  return imu;
}

void emit_alert(alert_level_t level, float az, a11y_profile_t profile)
{
  int side = (az < -20.f) ? -1 : (az > 20.f) ? 1 : 0;
  if (profile != PROFILE_VISION)
    haptic_play(level, side);      /* 听障/通用：震动为主 */
  if (profile == PROFILE_VISION || profile == PROFILE_GENERAL)
    earcon_play(level, side);      /* 视障强调短耳标；通用可选 */
  /* PROFILE_HEARING：默认不播语音长句 */
}
```

